package org.tenshu.core.common.legal

/**
 * Where Tenshu's privacy policy lives, and which translation a reader gets.
 *
 * App Store guideline 5.1.1(i) and Google Play's User Data policy both require the policy to be
 * reachable **inside** each app, so every app's settings / profile / about screen links it (see
 * `docs/how-to/app-store-release.md`). The page is static, generated by the apex's support-page
 * build (`web/apex/support-pages/privacy.ts`), one per language at `/legal/privacy/<lang>`.
 *
 * ⚠⚠ This is one of three copies of the same rule, because three toolchains have to open the link
 * and none of them can call the others: this one (Compose, Android + desktop), the Swift
 * `PrivacyPolicy` in `ios-release/Sources/PrivacyPolicy.swift` (every iOS app) and the TypeScript
 * `privacyPolicyUrl` in `web/shared/legal.ts` (apex + web Drive). `PrivacyPolicyParityTest`
 * (`:ui-core`) pins the other two to this one — change all three together.
 *
 * ⚠ The per-language URLs this builds are linked from shipped apps: never move them. The stores
 * carry the language-neutral `/legal/privacy` instead (store/shared/en-US/privacy_url.txt), which
 * the apex's Caddy redirects by Accept-Language. ⚖️ The German text is the binding one; the others
 * are translations.
 */
object PrivacyPolicy {
    /** The policy's path on tenshu.app, without the language segment. */
    const val BASE_URL: String = "https://tenshu.app/legal/privacy"

    /** The languages the policy is published in. Anything else falls back to [FALLBACK_LANGUAGE]. */
    val LANGUAGES: List<String> = listOf("de", "en", "fr")

    /** The translation a reader in any other language gets. */
    const val FALLBACK_LANGUAGE: String = "en"

    /**
     * The published language for [languageTag] — a BCP 47 tag (`de-AT`), a Java/POSIX locale
     * (`de_CH`), or a bare ISO 639 code (`fr`), any case. `null`, blank, or a language the policy
     * is not published in gives [FALLBACK_LANGUAGE].
     */
    fun languageFor(languageTag: String?): String {
        val language = languageTag
            ?.trim()
            ?.substringBefore('-')
            ?.substringBefore('_')
            ?.lowercase()
            .orEmpty()
        return if (language in LANGUAGES) language else FALLBACK_LANGUAGE
    }

    /** The policy's URL for a reader whose device or app language is [languageTag]. */
    fun url(languageTag: String?): String = "$BASE_URL/${languageFor(languageTag)}"
}
